validator:
function validate(input) {
  const [{ Cinema = [] }] = input;
  const seen = new Set();
  for (const [id, free] of Cinema) {
    if (!Number.isInteger(id) || id < 1) return 'Every seat_id must be a positive integer.';
    if (seen.has(id)) return `seat_id ${id} appears twice.`;
    seen.add(id);
    if (![0, 1, true, false].includes(free)) return `Seat ${id} needs free = 0 or 1.`;
  }
  for (let id = 1; id <= Cinema.length; id++) if (!seen.has(id)) return `Seats must be numbered 1 to ${Cinema.length}; seat ${id} is missing.`;
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const n = small ? Math.floor(rand() * 9) : 2000;
  const share = small ? 0.3 + rand() * 0.5 : 0.8;
  const Cinema = [];
  for (let id = 1; id <= n; id++) Cinema.push([id, rand() < share ? 1 : 0]);
  // Shuffle the row order so solutions cannot rely on rows arriving sorted.
  for (let i = Cinema.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Cinema[i], Cinema[j]] = [Cinema[j], Cinema[i]];
  }
  return [{ Cinema }];
}
